"""Further Mathematics (A Level, Lower Sixth): practice sets for 3D Vector Geometry, Hyperbolic Functions & Polar
Coordinates, Conic Sections & Rational Functions and the Examination module, plus two mock papers.

KKEVO draft content. Mock paper timings are KKEVO practice settings, not official examination times.
Paper 1 mock A: 50 four-option multiple-choice questions across all six Lower Sixth modules (concept = topic title).
Paper 2 practice paper A: auto-markable parts (multiple choice and numeric) in numbered questions of mixed topics.
"""

from .dsl import *  # noqa: F403

COURSE = ("further-mathematics", "lower-sixth")


def mc(prompt, right, wrong, pos, steps, concept, skill, hint, feedback="", diagram="", diagram_alt=""):
    """Four-option question: `right` is the correct option, `wrong` is three (text, why) pairs, `pos` (0-3) places the right one."""
    opts = [C(t, why=w) for t, w in wrong]
    opts.insert(pos, C(right, correct=True))
    return MC(prompt, opts, steps=steps, concept=concept, skill=skill, hint=hint, feedback=feedback,
              diagram=diagram, diagram_alt=diagram_alt)


