# ---------------------------------------------------------------- Set 5: hyperbolic functions and identities
HF_5 = [
    mc(r"Which identity is correct for all real $x$?", r"$\cosh^2 x - \sinh^2 x = 1$",
       [(r"$\cosh^2 x + \sinh^2 x = 1$", r"This is the trigonometric form with the wrong signs. At $x = 1$ it gives $2.38 + 1.38 \ne 1$."),
        (r"$\sinh^2 x - \cosh^2 x = 1$", "This has the terms the wrong way round: at $x = 0$ it gives $-1$."),
        (r"$\cosh x - \sinh x = 1$", r"This is true only at $x = 0$. In fact $\cosh x - \sinh x = e^{-x}$.")], 0,
       [S("Square the definitions and subtract", math=r"\cosh^2 x - \sinh^2 x = \frac{(e^x + e^{-x})^2 - (e^x - e^{-x})^2}{4} = \frac{4}{4} = 1")],
       "The basic hyperbolic identity", "Recall", r"Test $x = 0$ and $x = 1$ in each option."),
    mc(r"Find $\cosh(\ln 2)$.", r"$\dfrac{5}{4}$",
       [(r"$\dfrac{3}{4}$", r"This is $\sinh(\ln 2) = \frac{2 - \frac{1}{2}}{2}$: you subtracted instead of adding."),
        (r"$\dfrac{5}{2}$", "You added $2 + \\frac{1}{2}$ but forgot to divide by $2$."),
        (r"$2$", r"This is $e^{\ln 2}$, only the first term of the definition.")], 1,
       [S("Use the definition", math=r"\cosh(\ln 2) = \frac{e^{\ln 2} + e^{-\ln 2}}{2} = \frac{2 + \frac{1}{2}}{2} = \frac{5}{4}")],
       "Values of cosh", "Calculation", r"Write $e^{\ln 2} = 2$ and $e^{-\ln 2} = \frac{1}{2}$."),
    NUM(r"Given $\sinh x = \dfrac{3}{4}$, find $e^{x}$.", 2, tolerance=0.001,
        steps=[S("Find $\\cosh x$ from the identity", math=r"\cosh^2 x = 1 + \tfrac{9}{16} = \tfrac{25}{16} \Rightarrow \cosh x = \tfrac{5}{4}"),
               S("$e^x = \\cosh x + \\sinh x$", math=r"e^x = \tfrac{5}{4} + \tfrac{3}{4} = 2")],
        concept="Using the basic identity", skill="Calculation", hint=r"Find $\cosh x$ first; $\cosh x + \sinh x$ gives $e^x$."),
    NUM(r"Solve $5\cosh x - 3\sinh x = 4$. Give $x$ to 3 decimal places.", 0.693, tolerance=0.001,
        steps=[S("Use the definitions", math=r"e^x + 4e^{-x} = 4"),
               S("Multiply by $e^x$", math=r"e^{2x} - 4e^x + 4 = 0 \Rightarrow (e^x - 2)^2 = 0"),
               S("Solve", math=r"e^x = 2 \Rightarrow x = \ln 2 \approx 0.693")],
        concept="Equations in terms of e^x", skill="Calculation", hint=r"Write $\cosh x$ and $\sinh x$ with $e^x$ and $e^{-x}$; you get a quadratic in $e^x$."),
    mc(r"Using Osborn's rule, the hyperbolic form of $\sin 3A = 3\sin A - 4\sin^3 A$ is", r"$\sinh 3A = 3\sinh A + 4\sinh^3 A$",
       [(r"$\sinh 3A = 3\sinh A - 4\sinh^3 A$", r"The term $\sin^3 A$ contains a product of two sines, so its sign must change."),
        (r"$\cosh 3A = 3\cosh A + 4\cosh^3 A$", "The sines should become sinh, not cosh, and no cosh function should appear."),
        (r"$\sinh 3A = -3\sinh A + 4\sinh^3 A$", "Only the sign of the product term changes, not the sign of the single-sine term.")], 2,
       [S("Replace sin by sinh", math=r"\sinh 3A = 3\sinh A - 4\sinh^3 A"),
        S("Change the sign of the term containing $\\sinh^2$ (a product of two sines)", math=r"\sinh 3A = 3\sinh A + 4\sinh^3 A"),
        S("Check at $A = 1$", math=r"\sinh 3 = 10.018 = 3(1.1752) + 4(1.1752)^3")],
       "Osborn's rule", "Application", "Which terms contain a product of two sines?"),
    mc(r"Which of these functions is even?", r"$\cosh x$",
       [(r"$\sinh x$", r"$\sinh(-x) = -\sinh x$: it is odd."),
        (r"$\tanh x$", r"$\tanh(-x) = -\tanh x$: it is odd."),
        (r"$x\cosh x$", r"This is odd: an odd function $x$ times an even one gives an odd one.")], 3,
       [S("Use the definitions", math=r"\cosh(-x) = \frac{e^{-x} + e^{x}}{2} = \cosh x")],
       "Symmetry of hyperbolic functions", "Concept", r"Replace $x$ by $-x$ in the definition."),
    NUM(r"Solve $\cosh 2x - 3\sinh x = 3$ for the positive $x$, to 3 decimal places.", 1.444, tolerance=0.001,
        steps=[S("Use $\\cosh 2x = 1 + 2\\sinh^2 x$", math=r"2\sinh^2 x - 3\sinh x - 2 = 0 \Rightarrow (2\sinh x + 1)(\sinh x - 2) = 0"),
               S("The positive solution has $\\sinh x = 2$", math=r"x = \ln\left(2 + \sqrt{5}\right) \approx 1.444")],
        concept="Equations using identities", skill="Application", hint=r"Write $\cosh 2x$ in terms of $\sinh x$ and factorise the quadratic."),
    NUM(r"The equation $3\cosh x + \sinh x = 3$ has two real solutions. Find their sum, to 3 decimal places.", -0.693, tolerance=0.001,
        steps=[S("Substitute the definitions", math=r"2e^x + e^{-x} = 3 \Rightarrow 2e^{2x} - 3e^x + 1 = 0 \Rightarrow (2e^x - 1)(e^x - 1) = 0"),
               S("Solve", math=r"e^x = \tfrac{1}{2} \text{ or } 1 \Rightarrow x = -\ln 2 \text{ or } 0"),
               S("Add", math=r"-\ln 2 + 0 \approx -0.693")],
        concept="Equations in terms of e^x", skill="Reasoning", hint=r"You get a quadratic in $e^x$ with two positive roots."),
]

